+/* =========================================================================================
+   base
+   ========================================================================================= */
+html { background: var(--lf-bg) !important; }
+body {
+  background-color: var(--lf-bg) !important;
+  background-image: var(--lf-canvas-img) !important;
+  background-size: var(--lf-canvas-size, auto) !important;
+  background-attachment: fixed !important;
+  color: var(--lf-text);
+  font-family: var(--lf-font);
+  -webkit-font-smoothing: antialiased;
+  text-rendering: optimizeLegibility;
+}
+html[data-lf-style="soft"] body::before {
+  content: ""; position: fixed; inset: -12vmax; z-index: -1; pointer-events: none;
+  background: var(--lf-aurora);
+  filter: blur(40px) saturate(120%);
+  animation: lf-drift 42s ease-in-out infinite alternate;
+}
+@keyframes lf-drift {
+  0% { transform: translate3d(0, 0, 0) rotate(0deg) scale(1); }
+  50% { transform: translate3d(3vmax, -2vmax, 0) rotate(8deg) scale(1.06); }
+  100% { transform: translate3d(-3vmax, 2vmax, 0) rotate(-6deg) scale(1.02); }
+}
+::selection { background: color-mix(in srgb, var(--lf-accent) 24%, transparent); }
+.gradio-container {
+  overflow-x: clip !important; overflow-y: visible !important;
+  background: transparent !important; padding: 0 !important; max-width: none !important;
+  font-family: var(--lf-font) !important; font-size: 14px; line-height: 1.55;
+}
+.gradio-container > main, .gradio-container main.fillable, .gradio-container .main,
+.gradio-container .wrap:not(.default):not(.center):not(.hide) > .contain {
+  padding: 0 !important; margin: 0 !important; max-width: none !important;
+}
+footer { display: none !important; }
+.lf-offscreen { position: absolute !important; left: -10000px !important; width: 1px !important; height: 1px !important;
+  overflow: hidden !important; }
+.lf-stage-left { border: 1px dashed var(--lf-line-2); border-radius: var(--lf-r-md); padding: 12px; }
+#lf-overlays { position: static !important; gap: 0 !important; }
+#lf-runstate-box { display: none !important; }
+
+*::-webkit-scrollbar { width: 10px; height: 10px; }
+*::-webkit-scrollbar-thumb { background-color: color-mix(in srgb, var(--lf-text-4) 45%, transparent); border-radius: 10px;
+  border: 3px solid transparent; background-clip: padding-box; }
+*::-webkit-scrollbar-thumb:hover { background-color: color-mix(in srgb, var(--lf-text-4) 70%, transparent); }
+*::-webkit-scrollbar-track { background: transparent; }
+
+/* Gradio blocks are layout wrappers here: never clip, never round (fixes clipped first glyphs) */
+.gradio-container .block:not(.lf-acc):not(.lf-log):not(.lf-plot) { border-radius: 0 !important;
+  background: transparent !important; box-shadow: none !important; border: 0 !important; }
+.gradio-container .block:has(> .html-container), .gradio-container .block:has(> div > [data-testid="markdown"]),
+.gradio-container .block.hide-container { overflow: visible !important; padding: 0 !important; }
+.gradio-container .html-container { padding: 0 !important; }
+.gradio-container .prose { font-family: var(--lf-font) !important; }
+
+/* =========================================================================================
+   sidebar
+   ========================================================================================= */
+#lf-nav {
+  position: fixed !important;
+  top: var(--lf-nav-inset); left: var(--lf-nav-inset); bottom: var(--lf-nav-inset);
+  width: var(--lf-nav-w) !important; min-width: 0 !important; max-width: none !important;
+  z-index: 40;
+  display: flex !important; flex-direction: column !important; gap: 0 !important;
+  padding: 16px 12px 14px !important;
+  background: var(--lf-nav-bg);
+  border-right: 1px solid var(--lf-nav-line);
+  overflow-y: auto; overflow-x: hidden;
+  color: var(--lf-nav-text);
+  transition: width .22s cubic-bezier(.2, .8, .2, 1), padding .22s ease;
+  scrollbar-width: none;
+}
+#lf-nav::-webkit-scrollbar { display: none; }
+html[data-lf-style="soft"] #lf-nav {
+  border: 1px solid var(--lf-nav-line); border-radius: 26px;
+  box-shadow: inset 0 1px 0 rgba(255, 255, 255, .6), 0 30px 60px -36px rgba(49, 46, 129, .45);
+}
+html[data-lf-style="soft"] #lf-nav::before {
+  content: ""; position: absolute; inset: 0; z-index: -1; border-radius: inherit;
+  -webkit-backdrop-filter: blur(26px) saturate(170%); backdrop-filter: blur(26px) saturate(170%);
+}
+html[data-lf-style="soft"][data-lf-mode="dark"] #lf-nav { box-shadow: inset 0 1px 0 rgba(255, 255, 255, .06), 0 30px 60px -30px rgba(0, 0, 0, .8); }
+#lf-nav-body, #lf-nav .html-container { overflow: visible !important; }
