+.lf-nav-top { display: flex; align-items: center; gap: 8px; padding: 2px 2px 14px; }
+.lf-brand { display: flex; align-items: center; gap: 11px; min-width: 0; flex: 1 1 auto; }
+.lf-mark {
+  width: 32px; height: 32px; flex: 0 0 32px; border-radius: 9px;
+  background: linear-gradient(135deg, var(--lf-mark-a), var(--lf-mark-b));
