+.lf-hero-name { margin-top: 6px; font: 700 26px/1.2 var(--lf-font-display); letter-spacing: -.02em; color: var(--lf-text); word-break: break-all; }
+html[data-lf-style="eng"] .lf-hero-name { font-family: var(--lf-font-num); font-weight: 600; font-size: 24px; letter-spacing: -.01em; }
+.lf-hero-path { margin-top: 6px; font: 500 12px var(--lf-font-num); color: var(--lf-text-3); word-break: break-all; }
+.lf-hero-tags { display: flex; gap: 6px; flex-wrap: wrap; justify-content: flex-end; }
+.lf-hero-tags .tg { font-size: 12px; padding: 5px 9px; }
+.lf-hero-empty { font-size: 13.5px; color: var(--lf-text-3); padding: 6px 0 2px; }
+.lf-hero-src { font: 500 11px var(--lf-font-num); color: var(--lf-text-4); }
+.lf-specs { display: grid; grid-template-columns: repeat(auto-fit, minmax(118px, 1fr)); border: 1px solid var(--lf-line); border-radius: var(--lf-r-md); overflow: hidden; }
+.lf-specs .sp { display: flex; flex-direction: column; gap: 5px; padding: 12px 14px; border-right: 1px solid var(--lf-line); margin-right: -1px; }
+.lf-specs .k { font-size: 11.5px; color: var(--lf-text-3); white-space: nowrap; }
+.lf-specs .v { font: 600 16px/1.2 var(--lf-font-num); color: var(--lf-text); white-space: nowrap; }
+html[data-lf-style="soft"] .lf-specs { border: 0; gap: 10px; overflow: visible; }
+html[data-lf-style="soft"] .lf-specs .sp { border: 1px solid var(--lf-card-line); border-radius: 16px; margin: 0; background: var(--lf-surface-2);
+  box-shadow: inset 0 1px 0 rgba(255, 255, 255, .5); }
+html[data-lf-style="soft"] .lf-specs .v { font-family: var(--lf-font-display); font-weight: 700; font-size: 17px; }
+.lf-scope { display: flex; flex-direction: column; gap: 10px; }
+.lf-scope-h { display: flex; align-items: center; justify-content: space-between; gap: 12px; flex-wrap: wrap; }
+.lf-scope-h .k { font-size: 12.5px; font-weight: 650; color: var(--lf-text-2); }
+.lf-legend { display: flex; gap: 14px; flex-wrap: wrap; }
+.lf-legend .lg { display: inline-flex; align-items: center; gap: 6px; font-size: 12px; color: var(--lf-text-3); }
+.lf-legend i { width: 12px; height: 12px; border-radius: 3px; display: inline-block; }
+.lf-legend .lg-train i { background: var(--lf-strip-train); }
+.lf-legend .lg-frozen i { background: var(--lf-strip-frozen); }
+.lf-legend .lg-adapter i { background: var(--lf-strip-frozen); box-shadow: inset 0 3px 0 var(--lf-accent-2); }
+.lf-legend .lg-quant i { background: repeating-linear-gradient(135deg, var(--lf-strip-quant) 0 2px, transparent 2px 4px), var(--lf-strip-frozen); }
+.lf-strip { display: flex; align-items: stretch; gap: 6px; height: 40px; }
+.lf-strip .blk { flex: 0 0 auto; display: grid; place-items: center; padding: 0 10px; border-radius: var(--lf-r-xs);
+  font-size: 11.5px; font-weight: 600; color: var(--lf-text-2); background: var(--lf-strip-frozen); white-space: nowrap; }
+.lf-strip .blk.train { background: var(--lf-strip-train); color: #fff; }
+.lf-strip .blk.tied { background: transparent; border: 1px dashed var(--lf-line-2); color: var(--lf-text-3); }
+.lf-strip .lys { flex: 1 1 auto; display: grid; grid-template-columns: repeat(var(--n), minmax(0, 1fr)); gap: 3px; min-width: 0; }
+.lf-strip .ly { position: relative; display: block; border-radius: 3px; background: var(--lf-strip-frozen); transition: background-color .3s ease; }
+.lf-strip .ly.train { background: var(--lf-strip-train); }
+html[data-lf-style="soft"] .lf-strip .ly.train { background: linear-gradient(180deg, var(--lf-accent-2), var(--lf-accent)); }
+.lf-strip .ly.quant { background: repeating-linear-gradient(135deg, var(--lf-strip-quant) 0 2px, transparent 2px 4px), var(--lf-strip-frozen); }
+.lf-strip .ly.ad::after { content: ""; position: absolute; left: 0; right: 0; top: 0; height: 30%; border-radius: 3px 3px 0 0; background: var(--lf-accent-2); }
+html[data-lf-style="eng"] .lf-strip .ly.ad::after { background: var(--lf-accent); }
+.lf-scope-t { font-size: 13px; color: var(--lf-text-2); }
+
+.lf-flow { display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); gap: 10px; }
+.lf-step {
+  position: relative; display: flex; align-items: center; gap: 12px; padding: 12px 14px; text-decoration: none !important; cursor: pointer;
+  border-radius: var(--lf-r-md); border: 1px solid var(--lf-card-line); background: var(--lf-surface); color: var(--lf-text-3) !important;
+  box-shadow: var(--lf-card-shadow); transition: border-color .15s ease, transform .15s ease, box-shadow .2s ease;
+}
+.lf-step:hover { border-color: color-mix(in srgb, var(--lf-accent) 50%, transparent); }
+html[data-lf-style="soft"] .lf-step:hover { transform: translateY(-2px); }
+.lf-step .n { flex: 0 0 26px; height: 26px; display: grid; place-items: center; border-radius: 50%; font: 600 12px/1 var(--lf-font-num);
+  color: var(--lf-accent-text); background: var(--lf-accent-soft); }
+html[data-lf-style="eng"] .lf-step .n { border-radius: 4px; }
+.lf-step .tx { display: flex; flex-direction: column; min-width: 0; }
+.lf-step b { font-size: 13.5px; font-weight: 620; color: var(--lf-text); white-space: nowrap; }
+.lf-step small { font-size: 11.5px; color: var(--lf-text-3); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
+.lf-step .lf-ic { margin-left: auto; flex: 0 0 auto; opacity: .45; }
+.lf-step[data-lf-go="model"] { border-color: color-mix(in srgb, var(--lf-accent) 45%, transparent); }
+.lf-step[data-lf-go="model"] .n { background: var(--lf-btn-primary); color: #fff; }
+
+/* =========================================================================================
+   chat
+   ========================================================================================= */
+#lfp-infer-chat_box { padding: var(--lf-card-pad) !important; gap: 16px !important; }
+#lfp-infer-chat_box .block { padding: 0 !important; }
+#lfp-infer-chat_box .bubble-wrap { background: var(--lf-surface-2) !important; border-radius: var(--lf-r-md) !important;
+  border: 1px solid var(--lf-line) !important; }
+#lfp-infer-chat_box .message-row .message, #lfp-infer-chat_box .message { border-radius: var(--lf-r-md) !important; font-size: 14px !important; }
+#lfp-infer-chat_box .user-row .message, #lfp-infer-chat_box .message.user { background: var(--lf-accent-soft) !important; border: 0 !important; }
+#lfp-infer-chat_box .bot-row .message, #lfp-infer-chat_box .message.bot { background: var(--lf-surface) !important; border: 1px solid var(--lf-line) !important; }
+
+/* =========================================================================================
+   dataset preview dialog (upstream .modal-box)
+   ========================================================================================= */
+.modal-box {
+  background: var(--lf-popover) !important; border: 0 !important; border-radius: var(--lf-r-lg) !important;
+  box-shadow: var(--lf-shadow-pop), 0 0 0 100vmax rgba(8, 10, 20, .35) !important;
+  padding: 20px !important; width: min(960px, calc(100vw - 48px)) !important; z-index: 1000 !important;
+}
+
+/* =========================================================================================
+   command palette & tooltips
+   ========================================================================================= */
+.lf-pal-back { position: fixed; inset: 0; z-index: 2000; display: none; align-items: flex-start; justify-content: center;
+  padding-top: 12vh; background: rgba(8, 10, 20, .32); }
+html[data-lf-style="soft"] .lf-pal-back { -webkit-backdrop-filter: blur(6px); backdrop-filter: blur(6px); background: rgba(30, 27, 75, .18); }
+.lf-pal-back.open { display: flex; animation: lf-fade .14s ease both; }
+.lf-pal {
+  width: min(640px, calc(100vw - 32px)); max-height: 70vh; display: flex; flex-direction: column; overflow: hidden;
+  background: var(--lf-popover); border-radius: calc(var(--lf-r-lg) + 2px); box-shadow: var(--lf-shadow-pop);
+  font-family: var(--lf-font); color: var(--lf-text);
+}
+.lf-pal-in { display: flex; align-items: center; gap: 12px; padding: 0 16px; height: 56px; border-bottom: 1px solid var(--lf-line); color: var(--lf-text-3); }
+.lf-pal-in input { flex: 1 1 auto; border: 0; outline: 0; background: transparent; font: inherit; font-size: 16px; color: var(--lf-text); }
+.lf-pal-in input::placeholder { color: var(--lf-text-4); }
+.lf-pal-list { overflow-y: auto; padding: 6px 8px 8px; }
+.lf-pal-cap { padding: 10px 10px 4px; font-size: 11px; font-weight: 650; letter-spacing: .1em; text-transform: uppercase; color: var(--lf-text-4); }
+.lf-pal-it { display: flex; align-items: baseline; gap: 10px; padding: 9px 10px; border-radius: var(--lf-r-sm); cursor: pointer; min-width: 0; }
+.lf-pal-it .tt { font-size: 14px; font-weight: 560; color: var(--lf-text); white-space: nowrap; }
+.lf-pal-it .sb { font-size: 12px; color: var(--lf-text-3); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; min-width: 0; }
+.lf-pal-it code { margin-left: auto; font: 500 11px var(--lf-font-num); color: var(--lf-text-4); white-space: nowrap; }
+.lf-pal-it.sel { background: var(--lf-accent-soft); }
+.lf-pal-it.sel .tt { color: var(--lf-accent-text); }
+.lf-pal-empty { padding: 26px 12px; text-align: center; font-size: 13px; color: var(--lf-text-3); }
+.lf-pal-foot { display: flex; gap: 18px; padding: 10px 16px; border-top: 1px solid var(--lf-line); font-size: 12px; color: var(--lf-text-3); }
+.lf-pal-foot em { font-style: normal; }
+.lf-pal-foot kbd { margin-right: 2px; }
+
+.lf-tip { position: fixed; z-index: 3000; display: none; pointer-events: none; padding: 6px 10px; border-radius: 8px;
+  font: 550 12.5px/1.3 var(--lf-font); white-space: nowrap; color: var(--lf-text); background: var(--lf-popover); box-shadow: var(--lf-shadow-pop); }
+
+/* =========================================================================================
+   focus, motion, responsive
+   ========================================================================================= */
+.gradio-container :is(a, button, [role="button"], input, textarea, select, summary):focus-visible,
+.lf-search:focus-visible, .lf-icon-btn:focus-visible { outline: 2px solid var(--lf-accent) !important; outline-offset: 2px !important; }
+@media (prefers-reduced-motion: reduce) {
+  *, *::before, *::after { transition: none !important; animation: none !important; scroll-behavior: auto !important; }
+}
+@media (max-width: 1360px) {
+  .lf-split { flex-wrap: wrap !important; }
+  .lf-split-side { flex: 1 1 100% !important; width: 100% !important; position: static !important; }
+  .lf-run { max-height: none; }
+  .lf-flow { grid-template-columns: repeat(3, minmax(0, 1fr)); }
+}
+@media (max-width: 900px) {
+  :root, html[data-lf-style] { --lf-page-pad: 16px; --lf-nav-inset: 0px !important; --lf-top-gap: 0px !important; }
+  #lf-nav { position: sticky !important; top: 0; left: 0; bottom: auto; width: 100% !important; flex-direction: row !important;
+    align-items: center; gap: 8px !important; padding: 8px 12px !important; border-radius: 0 !important; border-width: 0 0 1px !important; overflow-x: auto; }
+  :has(> #lf-nav) { flex-direction: column !important; }
+  #lf-nav, #lf-main { flex: 0 0 auto !important; width: 100% !important; }
+  #lf-nav-body, #lf-nav-body .html-container, #lf-nav-body .prose { display: flex !important; flex-direction: row; align-items: center;
+    gap: 8px; flex: 1 1 auto; min-width: 0; }
+  #lf-nav-body { overflow-x: auto !important; overflow-y: hidden !important; scrollbar-width: none; width: auto !important; flex: 1 1 0 !important; }
+  #lf-nav-foot { flex: 0 0 auto !important; width: auto !important; }
+  #lf-nav-foot .lf-seg button { padding: 0 10px !important; }
+  .lf-brand { flex: 0 0 auto; }
+  .lf-brand-t, .lf-nav-cap, .lf-collapse, .lf-search .tx, .lf-search kbd, #lf-lang-slot, #lf-vram-slot { display: none !important; }
+  .lf-nav-top { padding: 0; flex: 0 0 auto; }
+  .lf-search { width: 36px; padding: 0; justify-content: center; margin: 0; }
+  .lf-nav-list { flex-direction: row; }
+  .lf-nav-item { height: 34px; }
+  #lf-nav-foot { margin: 0 0 0 auto !important; padding: 0 !important; flex-direction: row !important; align-items: center; }
+  #lf-main { margin-left: 0 !important; }
+  #lf-ctx { top: 52px; }
+  #lf-resizer { display: none; }
+  .lf-ph { flex-direction: column; align-items: flex-start; }
+  .lf-flow { grid-template-columns: repeat(2, minmax(0, 1fr)); }
+  .lf-crumbs { display: none; }
+}
